// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        bool ok;
        string memory v;
        vm.prank(caller);
        try c.version() returns (string memory ret) {
            ok = true;
            v = ret;
        } catch {
            ok = false;
            v = "";
        }

        assertTrue(ok && (keccak256(abi.encodePacked(v)) == keccak256(abi.encodePacked("1.0.0"))));
    }
}
